def group_states(grid_world):
    # Define the grid and goal position
    grid = grid_world["grid"]
    goal = grid_world["goal"]

    # Find the goal position in the grid
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == goal:
                goal_position = (i, j)

    # Initialize a set to keep track of visited states
    visited = set()

    # Define the possible movements (up, down, left, right)
    movements = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Function to check if a position is valid
    def is_valid_position(position):
        x, y = position
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] != "X"

    # Function to perform BFS from a given state
    def bfs(state):
        queue = [(state, [state])]
        visited.add(state)
        group = []
        while queue:
            (vertex, path) = queue.pop(0)
            group.append(vertex)
            for movement in movements:
                new_position = (path[-1] // len(grid[0]) + movement[0], path[-1] % len(grid[0]) + movement[1])
                if is_valid_position(new_position) and grid[new_position[0]][new_position[1]] not in visited:
                    queue.append((grid[new_position[0]][new_position[1]], path + [grid[new_position[0]][new_position[1]]]))
                    visited.add(grid[new_position[0]][new_position[1]])
        return group

    # Group the states
    groups = []
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] != "X" and grid[i][j] not in visited:
                group = bfs(grid[i][j])
                groups.append(group)

    return groups

